-- Secure the commercial prospect workflow.
--
-- The public table used to be directly writable by every commercial user,
-- including its commission snapshots.  From this migration onward all writes
-- go through record_commercial_prospect_followup(), financial values are
-- derived server-side and every mutation is recorded in an append-only log.

-- Server-owned allow-list matching public/data/geneva-commercial-prospects.json
-- (4,323 unique SITG prospects, dataset collected on 2026-05-26).  Keeping
-- the catalogue in Postgres prevents arbitrary RPC calls from manufacturing
-- commission-bearing source identifiers that do not exist on the map.
CREATE TABLE IF NOT EXISTS public.commercial_prospect_catalog (
  source_objectid bigint PRIMARY KEY,
  dataset_version date NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT commercial_prospect_catalog_source_positive CHECK (source_objectid > 0)
);

INSERT INTO public.commercial_prospect_catalog (source_objectid, dataset_version)
