ALTER TABLE public.commercial_prospect_catalog ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.commercial_prospect_catalog
  FROM PUBLIC, anon, authenticated, service_role;

COMMENT ON TABLE public.commercial_prospect_catalog IS
  'Server-owned allow-list for the versioned Geneva commercial prospect dataset.';

CREATE OR REPLACE FUNCTION public.commercial_refusal_reason_codes_valid(p_codes text[])
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = public, pg_temp
AS $$
  SELECT
    COALESCE(cardinality(p_codes), 0) <= 18
    AND COALESCE((
      SELECT bool_and(code = ANY (ARRAY[
        'price_too_high',
        'commission_too_high',
        'already_with_competitor',
        'no_need',
        'no_time',
        'decision_maker_absent',
        'consult_partner',
        'contract_too_restrictive',
        'tools_not_useful',
        'unclear_roi',
        'tok_not_known_enough',
        'refuses_digital',
        'previous_bad_experience',
        'technical_constraints',
        'budget_unavailable',
        'seasonal_or_closing',
        'not_interested_unspecified',
        'other'
      ]::text[]))
      FROM unnest(COALESCE(p_codes, ARRAY[]::text[])) AS code
    ), true)
    AND COALESCE(cardinality(p_codes), 0) = COALESCE((
      SELECT count(DISTINCT code)::integer
      FROM unnest(COALESCE(p_codes, ARRAY[]::text[])) AS code
    ), 0);
$$;

REVOKE ALL ON FUNCTION public.commercial_refusal_reason_codes_valid(text[])
  FROM PUBLIC, anon, authenticated, service_role;

ALTER TABLE public.commercial_prospect_followups
  ADD COLUMN IF NOT EXISTS refusal_reason_codes text[] NOT NULL DEFAULT ARRAY[]::text[],
  ADD COLUMN IF NOT EXISTS refusal_other_text text;

-- Billing data only exists for a signed prospect.  The former NOT NULL/default
-- combination leaked a fictitious monthly billing period onto unsigned rows.
ALTER TABLE public.commercial_prospect_followups
  ALTER COLUMN signed_subscription_billing_period DROP NOT NULL,
  ALTER COLUMN signed_subscription_billing_period DROP DEFAULT;

-- Make the administrator-controlled profile an unambiguous source of truth.
ALTER TABLE public.commercial_compensation_profiles
  ADD COLUMN IF NOT EXISTS employment_ended_at date;

UPDATE public.commercial_compensation_profiles
SET employment_active = false,
    engaged_at = CASE
      WHEN engaged_at IS NOT NULL AND engaged_at <= (now() AT TIME ZONE 'Europe/Zurich')::date THEN engaged_at
      ELSE NULL
    END,
    employment_ended_at = CASE
      WHEN engaged_at IS NOT NULL AND engaged_at <= (now() AT TIME ZONE 'Europe/Zurich')::date
        THEN (now() AT TIME ZONE 'Europe/Zurich')::date
      ELSE NULL
    END,
    updated_at = now()
WHERE status IN ('sprint', 'inactive')
  AND employment_active;

UPDATE public.commercial_compensation_profiles
SET employment_active = true,
    engaged_at = COALESCE(engaged_at, (now() AT TIME ZONE 'Europe/Zurich')::date),
    employment_ended_at = NULL,
    updated_at = now()
WHERE status IN ('engaged', 'team_lead')
  AND NOT employment_active;

-- Preserve the remuneration already considered active by the production
-- system.  A legacy active profile with a future engagement date would
-- otherwise receive neither fixed salary nor reservation commissions until
-- that future date after the event ledger is introduced.
UPDATE public.commercial_compensation_profiles
SET engaged_at = (now() AT TIME ZONE 'Europe/Zurich')::date,
    employment_ended_at = NULL,
    updated_at = now()
WHERE employment_active
  AND status IN ('engaged', 'team_lead')
  AND (
    engaged_at IS NULL
    OR engaged_at > (now() AT TIME ZONE 'Europe/Zurich')::date
  );

DO $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.commercial_compensation_profiles profile
    WHERE profile.employment_active
      AND (
        profile.status NOT IN ('engaged', 'team_lead')
        OR profile.engaged_at IS NULL
        OR profile.engaged_at > (now() AT TIME ZONE 'Europe/Zurich')::date
      )
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'active commercial compensation profiles must have a non-future engagement date';
  END IF;
END
$$;

ALTER TABLE public.commercial_compensation_profiles
  DROP CONSTRAINT IF EXISTS commercial_compensation_profiles_employment_state_check,
  ADD CONSTRAINT commercial_compensation_profiles_employment_state_check
    CHECK (
      (
        employment_active
        AND status IN ('engaged', 'team_lead')
        AND engaged_at IS NOT NULL
        AND employment_ended_at IS NULL
      )
      OR (
        NOT employment_active
        AND status IN ('sprint', 'inactive')
        AND (
          (engaged_at IS NULL AND employment_ended_at IS NULL)
          OR (
            engaged_at IS NOT NULL
            AND employment_ended_at IS NOT NULL
            AND employment_ended_at >= engaged_at
          )
        )
      )
    ),
  DROP CONSTRAINT IF EXISTS commercial_compensation_profiles_no_self_lead_check,
  ADD CONSTRAINT commercial_compensation_profiles_no_self_lead_check
    CHECK (team_lead_id IS NULL OR team_lead_id <> user_id);

CREATE OR REPLACE FUNCTION public.validate_commercial_compensation_profile()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NEW.employment_active IS DISTINCT FROM (NEW.status IN ('engaged', 'team_lead')) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'employment_active must be controlled by the engaged or team_lead status';
  END IF;

  IF TG_OP = 'UPDATE'
    AND NEW.employment_active
    AND NOT OLD.employment_active
    AND NEW.engaged_at IS NOT DISTINCT FROM OLD.engaged_at
  THEN
    -- An old engagement date belongs to the closed interval. A reactivation
    -- starts today unless the administrator explicitly supplies another date.
    NEW.engaged_at := (now() AT TIME ZONE 'Europe/Zurich')::date;
  END IF;

  IF NEW.employment_active THEN
    IF NEW.engaged_at IS NULL OR NEW.engaged_at > (now() AT TIME ZONE 'Europe/Zurich')::date THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'active employment requires a non-future engaged_at date';
    END IF;

    IF TG_OP = 'UPDATE'
      AND OLD.employment_active
      AND NEW.engaged_at IS DISTINCT FROM OLD.engaged_at
      AND (OLD.status <> 'engaged' OR NEW.status <> 'engaged')
    THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'engaged_at can only be corrected while the commercial remains engaged';
    END IF;

    NEW.employment_ended_at := NULL;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NOT OLD.employment_active
      AND NEW.employment_ended_at IS DISTINCT FROM OLD.employment_ended_at
    THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'employment_ended_at is locked after deactivation';
    END IF;

    IF OLD.engaged_at IS NOT NULL THEN
      NEW.engaged_at := OLD.engaged_at;
      NEW.employment_ended_at := CASE
        WHEN OLD.employment_active THEN COALESCE(
          NEW.employment_ended_at,
          (now() AT TIME ZONE 'Europe/Zurich')::date
        )
        ELSE OLD.employment_ended_at
      END;
    END IF;

    IF NEW.employment_ended_at > (now() AT TIME ZONE 'Europe/Zurich')::date THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'employment_ended_at cannot be in the future';
    END IF;
  END IF;

  IF NEW.team_lead_id IS NOT NULL THEN
    IF NEW.team_lead_id = NEW.user_id THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A commercial cannot lead themself';
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM public.commercial_compensation_profiles lead_profile
      JOIN public.user_roles lead_role
        ON lead_role.user_id = lead_profile.user_id
       AND lead_role.role = 'commercial'::public.app_role
      WHERE lead_profile.user_id = NEW.team_lead_id
        AND lead_profile.status = 'team_lead'
        AND lead_profile.employment_active
    ) THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'team_lead_id must reference an active commercial team lead';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS validate_commercial_compensation_profile
  ON public.commercial_compensation_profiles;
CREATE TRIGGER validate_commercial_compensation_profile
  BEFORE INSERT OR UPDATE OF status, employment_active, engaged_at, employment_ended_at, team_lead_id
  ON public.commercial_compensation_profiles
  FOR EACH ROW EXECUTE FUNCTION public.validate_commercial_compensation_profile();

REVOKE ALL ON FUNCTION public.validate_commercial_compensation_profile()
