  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  commercial_user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE RESTRICT,
  status text NOT NULL,
  employment_active boolean NOT NULL,
  effective_from date NOT NULL,
  fixed_salary_monthly_chf numeric(10, 2) NOT NULL,
  team_lead_id uuid REFERENCES auth.users(id) ON DELETE RESTRICT,
  changed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT commercial_compensation_profile_events_status_check
    CHECK (status IN ('sprint', 'engaged', 'team_lead', 'inactive')),
  CONSTRAINT commercial_compensation_profile_events_fixed_check
    CHECK (fixed_salary_monthly_chf >= 0)
);

CREATE INDEX IF NOT EXISTS idx_commercial_compensation_profile_events_user_effective
  ON public.commercial_compensation_profile_events(commercial_user_id, effective_from DESC, created_at DESC);

INSERT INTO public.commercial_compensation_profile_events (
  commercial_user_id, status, employment_active, effective_from,
  fixed_salary_monthly_chf, team_lead_id, changed_by, created_at
)
SELECT
  ccp.user_id,
  ccp.status,
  ccp.employment_active,
  CASE
    WHEN ccp.employment_active THEN ccp.engaged_at
    ELSE COALESCE(
      ccp.employment_ended_at,
      ccp.sprint_started_at,
      ccp.created_at::date,
      (now() AT TIME ZONE 'Europe/Zurich')::date
    )
  END,
  CASE
    WHEN ccp.employment_active AND ccp.status = 'team_lead' THEN 3500
    WHEN ccp.employment_active THEN 2500
    ELSE 0
  END,
  ccp.team_lead_id,
  NULL,
  ccp.created_at
FROM public.commercial_compensation_profiles ccp
WHERE NOT EXISTS (
  SELECT 1
  FROM public.commercial_compensation_profile_events event
  WHERE event.commercial_user_id = ccp.user_id
);

ALTER TABLE public.commercial_compensation_profile_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS commercial_compensation_profile_events_select
  ON public.commercial_compensation_profile_events;
CREATE POLICY commercial_compensation_profile_events_select
  ON public.commercial_compensation_profile_events
  FOR SELECT TO authenticated
  USING (
    public.auth_is_super_admin()
    OR commercial_user_id = (SELECT auth.uid())
  );

REVOKE ALL ON TABLE public.commercial_compensation_profile_events
  FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON TABLE public.commercial_compensation_profile_events
  TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.audit_commercial_compensation_profile()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.commercial_compensation_profile_events (
      commercial_user_id,
      status,
      employment_active,
      effective_from,
      fixed_salary_monthly_chf,
      team_lead_id,
      changed_by,
      created_at
    )
    VALUES (
      NEW.user_id,
      NEW.status,
      NEW.employment_active,
      COALESCE(NEW.engaged_at, NEW.sprint_started_at, (now() AT TIME ZONE 'Europe/Zurich')::date),
      CASE
        WHEN NEW.employment_active AND NEW.status = 'team_lead' THEN 3500
        WHEN NEW.employment_active THEN 2500
        ELSE 0
      END,
      NEW.team_lead_id,
      auth.uid(),
      now()
    );
  ELSIF OLD.status IS DISTINCT FROM NEW.status
    OR OLD.employment_active IS DISTINCT FROM NEW.employment_active
    OR OLD.engaged_at IS DISTINCT FROM NEW.engaged_at
    OR OLD.team_lead_id IS DISTINCT FROM NEW.team_lead_id
  THEN
    -- Moving an engagement start later must explicitly cancel the obsolete
    -- interval before the corrected active event begins.
    IF OLD.employment_active
      AND NEW.employment_active
      AND NEW.engaged_at > OLD.engaged_at
    THEN
      INSERT INTO public.commercial_compensation_profile_events (
        commercial_user_id,
        status,
        employment_active,
        effective_from,
        fixed_salary_monthly_chf,
        team_lead_id,
        changed_by,
        created_at
      )
      VALUES (
        NEW.user_id,
        'inactive',
        false,
        OLD.engaged_at,
        0,
        NULL,
        auth.uid(),
        now()
      );
    END IF;

    INSERT INTO public.commercial_compensation_profile_events (
      commercial_user_id,
      status,
      employment_active,
      effective_from,
      fixed_salary_monthly_chf,
      team_lead_id,
      changed_by,
      created_at
    )
    VALUES (
      NEW.user_id,
      NEW.status,
      NEW.employment_active,
      CASE
        WHEN NEW.employment_active AND NOT OLD.employment_active THEN NEW.engaged_at
        WHEN NEW.employment_active AND NEW.engaged_at IS DISTINCT FROM OLD.engaged_at THEN NEW.engaged_at
        WHEN NOT NEW.employment_active AND OLD.employment_active THEN NEW.employment_ended_at
        ELSE (now() AT TIME ZONE 'Europe/Zurich')::date
      END,
      CASE
        WHEN NEW.employment_active AND NEW.status = 'team_lead' THEN 3500
        WHEN NEW.employment_active THEN 2500
        ELSE 0
      END,
      NEW.team_lead_id,
      auth.uid(),
      now()
    );
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS audit_commercial_compensation_profile
  ON public.commercial_compensation_profiles;
CREATE TRIGGER audit_commercial_compensation_profile
  AFTER INSERT OR UPDATE OF status, employment_active, engaged_at, employment_ended_at, team_lead_id
  ON public.commercial_compensation_profiles
  FOR EACH ROW EXECUTE FUNCTION public.audit_commercial_compensation_profile();

