);

ALTER TABLE public.commercial_prospect_followup_history
  ADD COLUMN IF NOT EXISTS change_reason text,
  DROP CONSTRAINT IF EXISTS commercial_prospect_followup_history_reason_length_check,
  ADD CONSTRAINT commercial_prospect_followup_history_reason_length_check
    CHECK (change_reason IS NULL OR char_length(change_reason) <= 1000);

COMMENT ON TABLE public.commercial_prospect_followup_history IS
